import { dim } from "../../ui/index.js";
import { formatBytes, logSuccess } from "../../utils/index.js";
function formatCount(count, noun) {
    return `${count} ${noun}${count === 1 ? "" : "s"}`;
}
export function displayBuildSuccess(stats, startTime, outputDir, dryRun) {
    const duration = ((Date.now() - startTime) / 1000).toFixed(2);
    logSuccess(`Built in ${duration}s`);
    console.log(`    ${formatCount(stats.pages, "page")}, ${formatCount(stats.chunks, "chunk")}, ${formatCount(stats.assets, "asset")}`);
    console.log(`    ${formatBytes(stats.totalSize)} in ${outputDir}`);
    if (dryRun && stats.ssgPaths?.length) {
        console.log(`    ${dim("SSG routes:")} ${stats.ssgPaths.join(", ")}`);
    }
    console.log();
}
